solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct Route { std::uint32_t network; int prefix; std::string via; };

static std::uint32_t maskOf(int prefix) { return prefix <= 0 ? 0u : prefix >= 32 ? 0xFFFFFFFFu : ~((1u << (32 - prefix)) - 1u); }

std::optional<std::string> nextHop(const std::vector<Route>& table, std::uint32_t destination)
{
    const Route* best{ nullptr };
    for (const Route& r : table)
    {
        const std::uint32_t mask{ maskOf(r.prefix) };
        if ((destination & mask) != (r.network & mask)) continue;
        if (!best || r.prefix > best->prefix) best = &r;
    }
    if (!best) return std::nullopt;
    return best->via;
}

std::vector<std::string> nextHops(const std::vector<Route>& table, const std::vector<std::uint32_t>& destinations)
{
    std::vector<std::string> out;
    for (std::uint32_t d : destinations) out.push_back(nextHop(table, d).value_or("unreachable"));
    return out;
}

unitTests:
static std::uint32_t ip(int a, int b, int c, int d) { return (static_cast<std::uint32_t>(a) << 24) | (b << 16) | (c << 8) | d; }
static const std::vector<Route> table{
    { ip(10, 0, 0, 0), 8, "A" },
    { ip(10, 1, 0, 0), 16, "B" },
    { ip(10, 1, 2, 0), 24, "C" },
    { ip(0, 0, 0, 0), 0, "default" },
};
TEST("the lesson's example") {
    CHECK_EQ(nextHop(table, ip(10, 1, 2, 9)).value_or("?"), std::string("C"));
    CHECK_EQ(nextHop(table, ip(10, 1, 9, 9)).value_or("?"), std::string("B"));
    CHECK_EQ(nextHop(table, ip(10, 9, 9, 9)).value_or("?"), std::string("A"));
    CHECK_EQ(nextHop(table, ip(8, 8, 8, 8)).value_or("?"), std::string("default"));
}
TEST("no default route") {
    const std::vector<Route> local{ { ip(192, 168, 1, 0), 24, "lan" }, { ip(127, 0, 0, 0), 8, "loopback" } };
    CHECK(!nextHop(local, ip(8, 8, 8, 8)).has_value());
    CHECK_EQ(nextHops(local, { ip(127, 0, 0, 1), ip(1, 1, 1, 1), ip(192, 168, 1, 50) }), (std::vector<std::string>{ "loopback", "unreachable", "lan" }));
}
TEST("ties, host routes and stray bits") {
    const std::vector<Route> t{ { ip(172, 16, 0, 0), 12, "first" }, { ip(172, 16, 0, 0), 12, "second" }, { ip(172, 16, 5, 9), 32, "host" }, { ip(172, 16, 5, 77), 24, "subnet" } };
    CHECK_EQ(nextHop(t, ip(172, 20, 0, 1)).value_or("?"), std::string("first"));
    CHECK_EQ(nextHop(t, ip(172, 16, 5, 9)).value_or("?"), std::string("host"));
    CHECK_EQ(nextHop(t, ip(172, 16, 5, 10)).value_or("?"), std::string("subnet"));
}

